SQL:
-- sgl.query(name: SortableQuotes, command: many)
-- sgl.sortable(order_by, [id, price, quote_date])
SELECT id, price, quote_date FROM quotes WHERE deleted_at IS NULL ORDER BY date(quote_date) DESC, id LIMIT ?;

-- sgl.query(name: AggregateOrdering, command: many)
SELECT category, GROUP_CONCAT(description ORDER BY lower(description) DESC SEPARATOR ',') AS names
FROM quotes GROUP BY category ORDER BY category;

-- sgl.query(name: GroupedWithHaving, command: many)
SELECT lower(category) AS kind, count(*) AS total, max(date(quote_date)) AS latest
FROM quotes GROUP BY lower(category) HAVING count(*) > ? AND max(price) < ? ORDER BY count(*) DESC, lower(category);

-- sgl.query(name: CommonTableExpression, command: many)
WITH recent AS (SELECT id, quote_date FROM quotes ORDER BY date(quote_date) DESC LIMIT 10)
SELECT id FROM recent ORDER BY date(quote_date) ASC, id;

-- sgl.query(name: UpsertQuote, command: exec)
INSERT INTO quotes (id, description, category, price, quote_date, customer_id) VALUES (?, ?, ?, ?, ?, ?)
ON DUPLICATE KEY UPDATE description = CONCAT('(', VALUES(description), ')'), price = GREATEST(price, VALUES(price));

-- sgl.query(name: CopyLatestQuote, command: exec)
INSERT INTO quotes (description, category, price, quote_date, customer_id)
SELECT description, category, price, quote_date, customer_id FROM quotes WHERE id = ? ORDER BY date(quote_date) DESC LIMIT 1;
